export default (target, name, descriptor) => {
    const fn = descriptor.value

    descriptor.value = function (...args) {
      const vm = fn.apply(this, args)

      return new Proxy(vm, {
        get (target, prop, receiver) {
          return Reflect.get(target, prop, receiver)
        }
      })
    }

    return descriptor
  }
}

