  after(function(done) {
    server.close(function(err) {
      if (err) throw err;

      httpsServer.close(function(err) {
        if (err) throw err;
        done();
      });
    });
  });

  it('toArray, 传入伪数组, 输出真正数组', function() {
    function aFunction() {
      expect(utils.toArray(arguments)).to.be.a('array');
      expect(utils.toArray(null)).to.be.a('array');
      expect(utils.toArray(undefined)).to.be.a('array');
      expect(utils.toArray(NaN)).to.be.a('array');
      expect(utils.toArray(1)).to.be.a('array');
      expect(utils.toArray('hi')).to.be.a('array');
      expect(utils.toArray({})).to.be.a('array');

    }

    aFunction(1, 2, 3);
  });

  it('getPath传入指定名称, 返回拼好的路径', function() {
    var options = {
      servicePrefix: 'http://localhost:8080',
      serverPath: 'http://cas.sdet.test.com',
      paths: {
        validate: '/cas/validate',
        serviceValidate: '/cas/serviceValidate',
        proxy: '/cas/proxy',
        login: '/cas/login',
        logout: '/cas/logout',
        proxyCallback: '/cas/proxyCallback',
        restletIntegration: '/cas/v1/tickets'
      }
    };

    expect(utils.getPath('login', options)).to.equal('http://cas.sdet.test.com/cas/login?service=' + encodeURIComponent('http://localhost:8080/cas/validate'));
    expect(utils.getPath('logout', options)).to.equal('http://cas.sdet.test.com/cas/logout?service=' + encodeURIComponent('http://localhost:8080/cas/validate'));
    expect(utils.getPath('pgtUrl', options)).to.equal('http://localhost:8080/cas/proxyCallback');

    // absolute path
    expect(utils.getPath('pgtUrl', {
      servicePrefix: 'http://localhost:8080',
      serverPath: 'http://cas.sdet.test.com',
      paths: {
        validate: '/cas/validate',
        serviceValidate: '/cas/serviceValidate',
        proxy: '/cas/proxy',
        login: '/cas/login',
        logout: '/cas/logout',
        proxyCallback: 'http://localhost:8080/cas/proxyCallback',
        restletIntegration: '/cas/v1/tickets'
      }
