    expect(utils.getPath('validate', options)).to.equal('http://localhost:8080/cas/validate');

    expect(utils.getPath('restletIntegration', options)).to.equal('http://cas.sdet.test.com/cas/v1/tickets');
  });

  it('isMatchRule校验规则符合预期', function() {
    var req = {
      path: '/'
    };

    expect(utils.isMatchRule(req, '/', '/')).to.be.true;
    expect(utils.isMatchRule(req, '/', '/api')).to.be.false;

    expect(utils.isMatchRule(req, '/', /\//)).to.be.true;
    expect(utils.isMatchRule(req, '/', /\/api/)).to.be.false;

    expect(utils.isMatchRule(req, '/', function(path, req) {
      return path === '/';
    })).to.be.true;

    expect(utils.isMatchRule(req, '/', function(path, req) {
      return path === '/api';
    })).to.be.false;
  });

  it('getOrigin能够获取正确原始路径', function() {
    var req = {
      originalUrl: '/api',
      query: {
        ticket: 'some ticket'
      }
    };
    expect(utils.getOrigin(req, {
      servicePrefix: 'http://localhost:8080',
      serverPath: 'http://cas.sdet.test.com',
      paths: {
        validate: '/cas/validate',
        serviceValidate: '/cas/serviceValidate',
        proxy: '/cas/proxy',
        login: '/cas/login',
        logout: '/cas/logout',
        proxyCallback: 'http://localhost:8080/cas/proxyCallback',
        restletIntegration: '/cas/v1/tickets'
      }
    })).to.equal('http://localhost:8080/api');
  });

  it('shouldIgnore能够正确的解析规则', function() {
    var req = {
      path: '/'
    };

    expect(utils.shouldIgnore(req, {
      match: ['/'],
      logger: loggerFactory
    })).to.be.false;

    expect(utils.shouldIgnore(req, {
      match: ['/api'],
      logger: loggerFactory
    })).to.be.true;

    expect(utils.shouldIgnore(req, {
      match: [/\//],
      logger: loggerFactory
    })).to.be.false;

    expect(utils.shouldIgnore(req, {
      match: [/\/api/],
      logger: loggerFactory
    })).to.be.true;

    expect(utils.shouldIgnore(req, {
      match: [function(pathname, req) {
        return pathname === '/';
      }],
      logger: loggerFactory
    })).to.be.false;

    expect(utils.shouldIgnore(req, {
      match: [function(pathname, req) {
        return pathname === '/api';
      }],
      logger: loggerFactory
    })).to.be.true;

    expect(utils.shouldIgnore(req, {
      ignore: ['/'],
      logger: loggerFactory
    })).to.be.true;

    expect(utils.shouldIgnore(req, {
      ignore: ['/api'],
      logger: loggerFactory
    })).to.be.false;

    expect(utils.shouldIgnore(req, {
      ignore: [/\//],
      logger: loggerFactory
    })).to.be.true;

    expect(utils.shouldIgnore(req, {
      ignore: [/\/api/],
      logger: loggerFactory
    })).to.be.false;

    expect(utils.shouldIgnore(req, {
      ignore: [function(pathname, req) {
        return pathname === '/';
      }],
      logger: loggerFactory
    })).to.be.true;

    expect(utils.shouldIgnore(req, {
      ignore: [function(pathname, req) {
        return pathname === '/api';
      }],
      logger: loggerFactory
    })).to.be.false;

    expect(utils.shouldIgnore(req, {
      ignore: [],
      match: [],
      logger: loggerFactory
    })).to.be.false;
  });

  it('getLastUrl能够正确的获取最后的访问路径, 并设置默认值', function() {

    var options = {
      servicePrefix: 'http://localhost:8080',
      serverPath: 'http://cas.sdet.test.com',
      paths: {
        validate: '/cas/validate',
        serviceValidate: '/cas/serviceValidate',
