    expect(utils.getLastUrl({
      session: {
        lastUrl: 'http://localhost:8080/'
      }
    }, options)).to.equal('http://localhost:8080/');

    expect(utils.getLastUrl({
      session: {
        lastUrl: 'http://localhost:8080/cas/validate'
      }
    }, options)).to.equal('/');

    expect(utils.getLastUrl({}, options)).to.equal('/');
  });

